/// Ищет тавтологию вида «корень родственное_слово» в тексте.
///
/// Возвращает корень, если в `text` (lowercase) найдены два слова с общим
/// корнем. Пример: «абажур абажурного» → Some("абажур").
///
/// Это упрощённая версия правила RussianWordRootRepeatRule из LanguageTool.
pub fn find_ru_word_root_tautology(text_lower: &str) -> Option<&'static str> {
    RU_WORD_ROOTS.iter().find_map(|(root, related)| {
        // Точное совпадение по словам (word boundary)
        let root_pat = format!(" {} ", root);
        let rel_pat = format!(" {} ", related);
        if text_lower.contains(&root_pat) && text_lower.contains(&rel_pat) {
            Some(*root)
        } else {
            None
        }
    })
}

/// Возвращает количество всех записей во всех таблицах замен.
/// Удобно для диагностики и тестов.
pub fn total_replacement_entries() -> usize {
    RU_REPLACEMENTS.len()
        + UK_REPLACEMENTS.len()
        + UK_REPLACEMENTS_SOFT.len()
        + UK_REPLACEMENTS_RENAMED.len()
        + UK_REPLACEMENTS_SPELLING_2019.len()
}

/// Возвращает количество всех корневых пар.
pub fn total_word_root_entries() -> usize {
    RU_WORD_ROOTS.len()
}

/// Возвращает количество всех семантических категорий (DTD-сущностей).
pub fn total_semantic_categories() -> usize {
    RU_WEEKDAYS.len()
        + RU_MONTHS.len()
        + RU_ABBREV_MONTHS.len()
        + RU_COLORS.len()
        + RU_NATIONS.len()
        + RU_TIME_WORDS.len()
        + RU_HUMAN_QUALITIES.len()
        + RU_DUAL_NUMBER_NOUNS.len()
        + RU_PREP_V_WORDS.len()
        + RU_PREP_NA_WORDS.len()
        + RU_PROFESSIONS.len()
        + RU_VVODNOE_WORDS.len()
        + RU_MISSING_YO_WORDS.len()
        + RU_DOUBLE_NUM_WORDS.len()
        + RU_ADJ_ENDINGS.len()
        + RU_SHORT_ADJ_INOE.len()
        + RU_SHORT_ADJ_DOUBLE.len()
        + RU_SHORT_VERB_WORDS.len()
        + RU_ROST_WORDS.len()
        + RU_ZAGL_WORDS.len()
        + RU_DEFIS_LIBO_WORDS.len()
}
